tasks.solution:
let speed = 0;
const speedText = document.querySelector("#speed");

// #boost ve #brake düğmelerini dinle
document.querySelector("#boost").addEventListener("click", () => {
  speed += 10;
  speedText.textContent = speed;
});

document.querySelector("#brake").addEventListener("click", () => {
  speed = Math.max(0, speed - 10);
  speedText.textContent = speed;
});

check.js:
assert($("#speed").textContent.trim() === "0", "Başlangıçta #speed 0 göstermeli.");
click("#boost"); click("#boost"); click("#boost");
assert(speed === 30 && $("#speed").textContent.trim() === "30", "3 kez Hızlan'a tıklayınca speed 30 olmalı ve #speed '30' göstermeli.");
click("#brake");
assert(speed === 20 && $("#speed").textContent.trim() === "20", "Yavaşla'ya tıklayınca hız 10 azalmalı.");
click("#brake"); click("#brake"); click("#brake");
assert(speed === 0 && $("#speed").textContent.trim() === "0", "Hız 0'ın altına inmemeli.");

