let launches = 0;
const launchBtn = document.querySelector("#launch");

function onLaunch() {
  // launches'ı artır, #info'ya yaz, dinleyiciyi kaldır
  launches++;
  document.querySelector("#info").textContent = "Kalkış! Motorlar çalıştı.";
  launchBtn.removeEventListener("click", onLaunch);
}

launchBtn.addEventListener("click", onLaunch);

check.js:
assert(launches === 0, "Tıklamadan önce launches 0 olmalı.");
click("#launch");
assert(launches === 1 && $("#info").textContent.trim() === "Kalkış! Motorlar çalıştı.", "Tıklayınca launches 1 olmalı ve #info 'Kalkış! Motorlar çalıştı.' yazmalı.");
click("#launch"); click("#launch");
assert(launches === 1, "İkinci tıklama sayılmamalı; dinleyiciyi removeEventListener ile kaldır.");

challenge.solution:
const menu = document.querySelector("#menu");

// menu'ye TEK bir click dinleyicisi ekle; e.target ile tıklanan düğmeyi bul
menu.addEventListener("click", (e) => {
  if (e.target.tagName !== "BUTTON") return;
  for (const b of menu.querySelectorAll("button")) {
    b.classList.remove("selected");
  }
  e.target.classList.add("selected");
  document.querySelector("#info").textContent = `Rota: ${e.target.textContent}`;
});

check.js:
const btns = $$("#menu button");
click(btns[1]);
assert($("#info").textContent.trim() === "Rota: Venüs", "Venüs'e tıklayınca #info 'Rota: Venüs' olmalı.");
assert(btns[1].classList.contains("selected"), "Tıklanan düğmeye selected sınıfı eklenmeli.");
click(btns[2]);
assert(btns[2].classList.contains("selected") && !btns[1].classList.contains("selected"), "Yalnızca son tıklanan düğmede selected olmalı.");
const li = document.createElement("li");
const extra = document.createElement("button");
extra.textContent = "Satürn";
li.append(extra);
$("#menu").append(li);
click(extra);
assert($("#info").textContent.trim() === "Rota: Satürn", "Sonradan eklenen düğmeler de çalışmalı: dinleyiciyi tek tek düğmelere değil #menu'ye ekle.");
click("#menu");
assert($("#info").textContent.trim() === "Rota: Satürn", "Düğme dışında bir yere tıklanınca hiçbir şey değişmemeli.");

