assert($("#theme-btn").textContent.trim() === "Açık tema", "Koyu temadayken düğmede 'Açık tema' yazmalı.");
click("#theme-btn");
assert(!document.body.classList.contains("dark") && $("#theme-btn").textContent.trim() === "Koyu tema", "İkinci tıklamada koyu tema kapanmalı ve düğmede 'Koyu tema' yazmalı.");

