project_task.solution:
function updateSummary() {
  const all = document.querySelectorAll(".task").length;
  const done = document.querySelectorAll(".task.done").length;
  document.querySelector("#summary").textContent = `${done}/${all} görev tamamlandı`;
}
updateSummary();

// her .done-btn düğmesine click dinleyicisi ekle
for (const btn of document.querySelectorAll(".done-btn")) {
  btn.addEventListener("click", () => {
    const li = btn.parentElement;
    li.classList.toggle("done");
    btn.textContent = li.classList.contains("done") ? "Geri al" : "Tamamla";
    updateSummary();
  });
}

check.js:
const btns = $$(".done-btn");
const items = $$(".task");
assert($("#summary").textContent.trim() === "1/4 görev tamamlandı", "Başlangıçta özet '1/4 görev tamamlandı' olmalı.");
click(btns[1]);
assert(items[1].classList.contains("done") && btns[1].textContent.trim() === "Geri al", "Tamamla'ya tıklayınca görev done olmalı ve düğmede 'Geri al' yazmalı.");
assert($("#summary").textContent.trim() === "2/4 görev tamamlandı", "Tıklayınca özet güncellenmeli: '2/4 görev tamamlandı'.");
click(btns[1]);
assert(!items[1].classList.contains("done") && btns[1].textContent.trim() === "Tamamla", "İkinci tıklamada görev geri alınmalı ve düğmede 'Tamamla' yazmalı.");
click(btns[0]);
assert(!items[0].classList.contains("done") && $("#summary").textContent.trim() === "0/4 görev tamamlandı", "Bütün düğmeler çalışmalı: ilk görev geri alınınca '0/4 görev tamamlandı'.");

