project_task.solution:
const question = { text: "Kızıl gezegen hangisi?", options: ["Mars", "Venüs", "Merkür"], answer: 0 };
let score = 0;

function showQuestion(q) {
  document.querySelector("#question").textContent = q.text;
  document.querySelectorAll(".option").forEach((btn, i) => {
    btn.textContent = q.options[i];
  });
}
showQuestion(question);

// seçenek düğmelerine click dinleyicisi ekle
const feedback = document.querySelector("#feedback");
document.querySelectorAll(".option").forEach((btn, i) => {
  btn.addEventListener("click", () => {
    if (i === question.answer) {
      feedback.textContent = "Doğru!";
      score += 10;
    } else {
      feedback.textContent = "Yanlış";
    }
    document.querySelector("#score").textContent = `Puan: ${score}`;
  });
});

check.js:
const btns = $$(".option");
click(btns[1]);
assert($("#feedback").textContent.trim() === "Yanlış", "Yanlış seçeneğe tıklayınca #feedback 'Yanlış' olmalı.");
assert(score === 0 && $("#score").textContent.trim() === "Puan: 0", "Yanlış cevap puanı artırmamalı; #score 'Puan: 0' olmalı.");
click(btns[0]);
assert($("#feedback").textContent.trim() === "Doğru!" && score === 10 && $("#score").textContent.trim() === "Puan: 10", "Doğru seçeneğe tıklayınca 'Doğru!' yazmalı, puan 10 olmalı ve #score 'Puan: 10' göstermeli.");
question.answer = 2;
click(btns[2]);
assert($("#feedback").textContent.trim() === "Doğru!" && score === 20, "Doğru cevabı tıklama anında question.answer'dan oku (elle 0 yazma).");
